<section class="aa-panel active" data-panel="periods"><div class="aa-grid"><article><header><h2>Periodos académicos</h2><button data-form="period">Nuevo periodo</button></header><?php foreach($academic['periods'] as $p):?><div class="aa-row"><div><strong><?=e($p['name'])?></strong><small><?=e($p['code'])?> · <?=e($p['starts_on'])?> al <?=e($p['ends_on'])?></small></div><span><?=e($p['status'])?></span></div><?php endforeach;?></article><article class="aa-promotion"><h2>Avance semestral</h2><?php if(!$academic['promotion']['source']):?><p>No existe un periodo activo.</p><?php else:?><p>Periodo actual: <strong><?=e($academic['promotion']['source']['name'])?></strong></p><p><?= (int)$academic['promotion']['students']?> estudiantes activos serán evaluados.</p><form id="promotionForm"><input type="hidden" name="_csrf" value="<?=e($academicCsrf)?>"><select name="target_period_id" required><option value="">Selecciona el siguiente periodo</option><?php foreach($academic['promotion']['targets'] as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select><button type="submit">Revisar y avanzar</button></form><small>La operación requiere confirmación y queda registrada en auditoría.</small><?php endif;?></article></div></section>
<section class="aa-panel" data-panel="catalogs"><div class="aa-catalogs"><article><header><h2>Carreras</h2><button data-form="career">Agregar</button></header><?php foreach($academic['careers'] as $i):?><p><strong><?=e($i['name'])?></strong><small><?=e($i['code'])?></small></p><?php endforeach;?></article><article><header><h2>Tipos de proyecto</h2><button data-form="type">Agregar</button></header><?php foreach($academic['types'] as $i):?><p><strong><?=e($i['name'])?></strong><small><?=e($i['code'])?></small></p><?php endforeach;?></article><article><header><h2>Líneas de investigación</h2><button data-form="line">Agregar</button></header><?php foreach($academic['lines'] as $i):?><p><strong><?=e($i['name'])?></strong><small><?=e($i['career_name']?:'Todas las carreras')?></small></p><?php endforeach;?></article></div></section>
<section class="aa-panel" data-panel="subjects"><article class="aa-subjects"><header><h2>Asignaturas</h2><button data-form="subject">Nueva asignatura</button></header><?php if(!$academic['subjects']):?><div class="aa-empty">Aún no hay asignaturas registradas.</div><?php else:foreach($academic['subjects'] as $i):?><div class="aa-row"><div><strong><?=e($i['name'])?></strong><small><?=e($i['code'])?> · <?=e($i['career_name'])?> · <?=$i['semester']?>.º semestre</small></div><span><?=e($i['teacher_name']?:'Sin docente')?></span></div><?php endforeach;endif;?></article></section>
